  "privOther": "Ostale postojeće funkcije",
  "privProviders": "Pružaoci usluga i međunarodni prenosi",
  "privRetention": "Čuvanje i brisanje",
  "privRights": "Vaša prava",
  "noticeReopen": "Obaveštenje o skladištu",
  "noticeLabel": "Obaveštenje o skladištu pregledača",
  "noticeText": "Cook koristi skladište pregledača za funkcije kuvanja i prijave koje koristite. Ne dodaje se skladište za oglašavanje ni analitiku.",
  "noticeClose": "Zatvori obaveštenje o skladištu",
  "privDraftLabel": "Nacrt — ažurirano 28. oktobra 2026.",
  "privDraft": "Funkcije naloga se trenutno testiraju. Podatke o rukovaocu i uslugama u nastavku treba dopuniti pre javnog pokretanja.",
  "privWho1": "Cook vodi [zvaničan naziv i poštanska adresa rukovaoca]. Za pitanja i zahteve o privatnosti pišite na [imejl adresa za privatnost]. Ove podatke treba dopuniti pre otvaranja registracije.",
  "privWhat1": "Kada napravite nalog, koristimo vaš imejl, identifikator naloga, zapise o autentifikaciji lozinkom i status potvrde kako bismo pružili i zaštitili vaš nalog. Lozinke pružalac autentifikacije obrađuje kao bezbedne heševe; Cook ne čuva čitljive lozinke. Čuvamo raspored kuhinje, izabrani jezik, temu i merne jedinice kako bismo vratili vaša podešavanja na svim uređajima. Za nalog su potrebni imejl i lozinka; recepte možete pregledati i bez naloga.",
  "privWhat2": "Obrada naloga i podešavanja neophodna je za pružanje usluge naloga koju tražite (član 6. stav 1. tačka (b) GDPR-a). Ograničeni zapisi o bezbednosti i sprečavanju zloupotrebe mogu se obrađivati na osnovu legitimnih interesa (član 6. stav 1. tačka (f)), u neophodnoj meri i nakon odmeravanja interesa. Imejlovi za potvrdu i resetovanje lozinke su servisne poruke, a ne marketing. Funkcija naloga ne dodaje oglašavanje ni analitiku.",
  "privStorage1": "Cook koristi sessionStorage za prenos vaše kuhinje, napretka u kuvanju i izbora između stranica u istoj kartici. Kada ste prijavljeni, sadrži i vašu sesiju prijave. Pregledač to obično briše kada se sesija kartice završi, ali vraćanje sesije pregledača može to zadržati. Odjava briše Cook podatke kartice. Zatvaranje obaveštenja o skladištu pamti se samo u toj kartici. Cook-ove sopstvene skripte ne postavljaju kolačiće. Vaši pružaoci hostinga ili usluga mogu imati sopstvenu bezbednosnu obradu koju treba dokumentovati pre pokretanja.",
  "privStorage2": "U redu i dugme za zatvaranje obaveštenja o skladištu samo zatvaraju obaveštenje. Ne odobravaju analitiku, oglašavanje ni drugo opciono praćenje. Svako buduće skladištenje koje nije neophodno zahtevaće poseban izbor pre početka, uz jednako lako odbijanje i povlačenje.",
  "privOther1": "Trenutna glasovna funkcija liste recepata na osnovu vaše IP adrese od country.is traži približnu državu kako bi izabrala jezik prepoznavanja govora. Ako koristite prepoznavanje preko mikrofona, pregledač može slati zvuk svom pružaocu prepoznavanja govora. Sastojke možete i otkucati. Ove pružaoce, njihove politike i pravni osnov ovih funkcija treba proveriti pre javnog pokretanja.",
  "privProviders1": "Planirani pružalac naloga: Supabase (upravljani PostgreSQL i autentifikacija) sa izabranim regionom baze podataka u EU. Pružalac imejla: [pružalac]. Hosting sajta: [pružalac]. Rukovalac mora da potvrdi stvarne pružaoce, ugovore o obradi, podobrađivače, lokacije zapisa i eventualne prenose van EEP-a. Region baze podataka u EU sam po sebi ne isključuje međunarodne prenose. Gde je primenljivo, navedite odluku o adekvatnosti ili ugovorne mere zaštite i kako dobiti njihovu kopiju.",
  "privRetention1": "Podešavanja naloga čuvaju se dok je vaš nalog aktivan. Brisanje možete zatražiti preko gore navedenog kontakta za privatnost. Pre pokretanja rukovalac mora da utvrdi postupak odgovaranja na zahteve za brisanje, istek nepotvrđenih naloga i rokove čuvanja bezbednosnih zapisa i rezervnih kopija. Obrisani podaci mogu ostati u rezervnim kopijama sa ograničenim pristupom do isteka dokumentovanog roka čuvanja.",
  "privRights1": "U zavisnosti od važećih uslova, možete zatražiti pristup, ispravku, brisanje, ograničenje ili prenosivost, odnosno uložiti prigovor na obradu zasnovanu na legitimnom interesu. Obratite se gore navedenom rukovaocu; na zahteve se obično odgovara u roku od mesec dana, a svako zakonito produženje se obrazlaže. Možete podneti pritužbu nadzornom organu, uključujući mađarski NAIH na naih.hu. Cook ne koristi podešavanja naloga za automatizovane odluke sa pravnim ili slično značajnim posledicama.",
  "favOnly": "Samo omiljeni",
  "favAdd": "Dodaj u omiljene",
  "favAdded": "Dodato u omiljene",
  "favSignIn": "Prijavite se da biste čuvali omiljene.",
