  "Fill the pot": "Napunite šerpu",
  "Fill the large pot with # L cold water. Don't add oil.": "Veliku šerpu napunite sa # l hladne vode. Ne dodajte ulje.",
  "Pot filled": "Šerpa napunjena",
  "Put it on the stove": "Stavite na šporet",
  "Put the pot on the largest burner, turn it to HIGH and put the lid on (it boils faster).": "Šerpu stavite na najveću ringlu, uključite na JAKO i poklopite poklopcem (brže provri).",
  "Lid on, burner on high": "Poklopac stavljen, ringla na jako",
  "Wait for the boil": "Sačekajte da provri",
  "Let the water come to a full rolling boil. Meanwhile, start the prep.": "Pustite da voda snažno provri. U međuvremenu počnite s pripremom.",
  "Big bubbles break the surface all the time": "Veliki mehurići stalno pucaju na površini",
  "Eggs out of the fridge": "Jaja iz frižidera",
  "Take the eggs out of the fridge so they warm up.": "Izvadite jaja iz frižidera da se zagreju.",
  "Eggs on the counter": "Jaja na radnoj površini",
  "Dice the guanciale": "Isecite guanciale na kockice",
  "Cut the guanciale into 1 cm cubes.": "Guanciale isecite na kockice od 1 cm.",
